inSequence.script:
var result = mc.getPayloadJSON();
                var cleanProducts = [];
                if (result && Array.isArray(result)) {
                    for (var i = 0; i < result.length; i++) {
                        var p = result[i];
                        cleanProducts.push({
                            id: parseInt(p.id),
                            ref: String(p.ref || ""),
                            name: String(p.label || p.ref || "Sản phẩm chưa đặt tên"),
                            price: parseFloat(p.price || p.price_ttc || 0),
                            description: String(p.description || ""),
                            stock: parseInt(p.stock_reel || 0),
                            img: (p.array_options && p.array_options.options_url_hinh_anh) ? p.array_options.options_url_hinh_anh : ''
                        });
                    }
                }
                mc.setPayloadJSON(cleanProducts);
